17			it('#{#rsz1a} - should preserve dimensions if image is smaller than max size', () => {
18				const result = calculateResizeDimensions(1000, 800, 2000);
19				expect(result).toEqual({ width: 1000, height: 800 });
20			});
21	
22			it('#{#rsz1a} - should preserve dimensions for exactly 2000px image', () => {
