39			it('#{#rsz1a} - should resize square image correctly', () => {
40				const result = calculateResizeDimensions(4000, 4000, 2000);
41				expect(result.width).toBe(2000);
42				expect(result.height).toBe(2000);
43			});
44	
45			it('#{#rsz1a} - should maintain aspect ratio for landscape image', () => {
46				const result = calculateResizeDimensions(4000, 3000, 2000);
47				const originalRatio = 4000 / 3000;
48				const newRatio = result.width / result.height;
49				expect(Math.abs(originalRatio - newRatio)).toBeLessThan(0.01);
