54				const originalRatio = 3000 / 4000;
55				const newRatio = result.width / result.height;
56				expect(Math.abs(originalRatio - newRatio)).toBeLessThan(0.01);
57			});
58	
59			it('#{#rsz1a} - should handle very wide panorama images', () => {
60				const result = calculateResizeDimensions(6000, 1500, 2000);
61				expect(result.width).toBe(2000);
62				expect(result.height).toBe(500);
63			});
64	
65			it('#{#rsz1a} - should handle very tall images', () => {
66				const result = calculateResizeDimensions(1500, 6000, 2000);
67				expect(result.width).toBe(500);
68				expect(result.height).toBe(2000);
