70	
71			it('#{#rsz1a} - should use default max size of 2000 when not provided', () => {
72				const result = calculateResizeDimensions(4000, 3000);
73				expect(result.width).toBe(2000);
74				expect(result.height).toBe(1500);
75			});
76	
77			it('#{#rsz1a} - should allow custom max size parameter', () => {
78				const result = calculateResizeDimensions(4000, 3000, 1000);
79				expect(result.width).toBe(1000);
80				expect(result.height).toBe(750);
81			});
82	
83			it('#{#rsz1b} - should round dimensions to whole pixels', () => {
84				const result = calculateResizeDimensions(3000, 2000, 2000);
85				expect(Number.isInteger(result.width)).toBe(true);
86				expect(Number.isInteger(result.height)).toBe(true);
87			});
88		});
