90		describe('resizeImage - Type Handling', () => {
91			it('#{#rsz1b} - should return original file for non-JPEG/PNG types', async () => {
92				const pdfFile = new File(['pdf data'], 'receipt.pdf', { type: 'application/pdf' });
93				const result = await resizeImage(pdfFile, 2000, 0.85);
94				expect(result).toBe(pdfFile);
95			});
96	
97			it('#{#rsz1b} - should return original file for HEIC images', async () => {
98				const heicFile = new File(['heic data'], 'receipt.heic', { type: 'image/heic' });
99				const result = await resizeImage(heicFile, 2000, 0.85);
100				expect(result).toBe(heicFile);
101			});
102	
103			it('#{#rsz1b} - should return original file for unsupported image types', async () => {
104				const webpFile = new File(['webp data'], 'receipt.webp', { type: 'image/webp' });
105				const result = await resizeImage(webpFile, 2000, 0.85);
106				expect(result).toBe(webpFile);
107			});
108		});
