155	describe('ReceiptImageViewer - Pan/Navigation', () => {
156		describe('#{#zom2a} Pan/Drag to Navigate', () => {
157			it('should initialize pan offset at 0,0', () => {
158				const panX = 0;
159				const panY = 0;
160	
161				expect(panX).toBe(0);
162				expect(panY).toBe(0);
163			});
164	
165			it('should update pan position when dragging', () => {
166				let panX = 0;
167				let panY = 0;
168	
169				const dragDeltaX = 50;
170				const dragDeltaY = 30;
171	
172				panX += dragDeltaX;
173				panY += dragDeltaY;
174	
175				expect(panX).toBe(50);
176				expect(panY).toBe(30);
177			});
178	
179			it('should calculate pan offset from drag start and current position', () => {
180				const dragStartX = 100;
181				const dragStartY = 150;
182				const currentX = 200;
183				const currentY = 250;
184	
185				const panX = currentX - dragStartX;
186				const panY = currentY - dragStartY;
187	
188				expect(panX).toBe(100);
189				expect(panY).toBe(100);
190			});
191	
192			it('should set dragging state to true on mouse down', () => {
193				let isDragging = false;
194				const zoom = 200; // Must be > 100%
195	
196				if (zoom > 100) {
197					isDragging = true;
198				}
199	
200				expect(isDragging).toBe(true);
201			});
202	
203			it('should set dragging state to false on mouse up', () => {
204				let isDragging = true;
205				isDragging = false; // Mouse up
206	
207				expect(isDragging).toBe(false);
208			});
209	
210			it('should not enable dragging at 100% zoom', () => {
211				let isDragging = false;
212				const zoom = 100;
213	
214				if (zoom > 100) {
215					isDragging = true;
216				}
217	
218				expect(isDragging).toBe(false);
219			});
220	
221			it('should use "grab" cursor when zoom > 100% and not dragging', () => {
222				const zoom = 150;
223				const isDragging = false;
224				const MIN_ZOOM = 100;
225	
226				const cursor = zoom > MIN_ZOOM ? (isDragging ? 'grabbing' : 'grab') : 'default';
227	
228				expect(cursor).toBe('grab');
