230	
231			it('should use "grabbing" cursor when dragging', () => {
232				const zoom = 150;
233				const isDragging = true;
234				const MIN_ZOOM = 100;
235	
236				const cursor = zoom > MIN_ZOOM ? (isDragging ? 'grabbing' : 'grab') : 'default';
237	
238				expect(cursor).toBe('grabbing');
239			});
240	
241			it('should use "default" cursor at 100% zoom', () => {
242				const zoom = 100;
243				const isDragging = false;
244				const MIN_ZOOM = 100;
245	
246				const cursor = zoom > MIN_ZOOM ? (isDragging ? 'grabbing' : 'grab') : 'default';
247	
248				expect(cursor).toBe('default');
249			});
250		});
251	
252		describe('#{#zom2b} Keyboard Navigation', () => {
253			it('should pan up by 50px on ArrowUp key', () => {
254				let panY = 0;
255				const PAN_STEP = 50;
256				const zoom = 200;
257	
258				if (zoom > 100) {
259					panY += PAN_STEP; // Pan up
260				}
261	
262				expect(panY).toBe(50);
263			});
264	
265			it('should pan down by 50px on ArrowDown key', () => {
266				let panY = 0;
267				const PAN_STEP = 50;
268				const zoom = 200;
269	
270				if (zoom > 100) {
271					panY -= PAN_STEP; // Pan down
272				}
273	
274				expect(panY).toBe(-50);
275			});
276	
277			it('should pan left by 50px on ArrowLeft key', () => {
278				let panX = 0;
279				const PAN_STEP = 50;
280				const zoom = 200;
281	
282				if (zoom > 100) {
283					panX += PAN_STEP; // Pan left
284				}
285	
286				expect(panX).toBe(50);
287			});
288	
289			it('should pan right by 50px on ArrowRight key', () => {
290				let panX = 0;
291				const PAN_STEP = 50;
292				const zoom = 200;
293	
294				if (zoom > 100) {
295					panX -= PAN_STEP; // Pan right
296				}
297	
298				expect(panX).toBe(-50);
299			});
300	
301			it('should not pan with arrow keys at 100% zoom', () => {
302				const panX = 0;
303				let panY = 0;
304				const PAN_STEP = 50;
305				const zoom = 100;
306	
307				if (zoom > 100) {
308					panY += PAN_STEP;
309				}
310	
311				expect(panX).toBe(0);
312				expect(panY).toBe(0);
313			});
314	
315			it('should support optional keyboard zoom shortcuts (+, -, 0)', () => {
316				let zoom = 100;
317				const ZOOM_STEP = 50;
318	
319				// + key: zoom in
320				zoom += ZOOM_STEP;
321				expect(zoom).toBe(150);
322	
323				// - key: zoom out
324				zoom -= ZOOM_STEP;
325				expect(zoom).toBe(100);
