335	describe('ReceiptImageViewer - Mobile Support', () => {
336		describe('#{#zom3a} Touch Gestures', () => {
337			it('should calculate distance between two touch points', () => {
338				const touch1 = { clientX: 0, clientY: 0 };
339				const touch2 = { clientX: 100, clientY: 0 };
340	
341				const dx = touch2.clientX - touch1.clientX;
