393	
394			it('should implement double tap to zoom to 200%', () => {
395				let zoom = 100;
396				const tapCount = 2;
397	
398				if (tapCount === 2 && zoom === 100) {
399					zoom = 200;
400				}
401	
402				expect(zoom).toBe(200);
403			});
404	
405			it('should implement double tap when zoomed to reset to 100%', () => {
406				let zoom = 250;
407				const tapCount = 2;
408	
409				if (tapCount === 2 && zoom > 100) {
410					zoom = 100;
411				}
412	
413				expect(zoom).toBe(100);
414			});
415		});
416	
417		describe('#{#zom3b} Prevent Browser Default Zoom', () => {
418			it('should set touch-action to none to prevent browser gestures', () => {
419				const touchAction = 'none';
420				expect(touchAction).toBe('none');
421			});
422	
423			it('should prevent default on wheel events', () => {
424				const mockEvent = {
425					preventDefault: vi.fn(),
426					deltaY: -1
427				};
428	
429				mockEvent.preventDefault();
430	
431				expect(mockEvent.preventDefault).toHaveBeenCalled();
432			});
433	
434			it('should prevent image selection during drag', () => {
435				const userSelect = 'none';
436				expect(userSelect).toBe('none');
437			});
438		});
