16	describe('Receipt Image Click Opens Editor', () => {
17		const receiptsPagePath = join(process.cwd(), 'src/routes/receipts/+page.svelte');
18		const pageContent = readFileSync(receiptsPagePath, 'utf-8');
19	
20		describe('#{#ric1a} Image Thumbnail Click Opens Edit Modal', () => {
21			it('should NOT have target="_blank" links wrapping receipt image thumbnails', () => {
22				// The image thumbnail should not be wrapped in an <a target="_blank"> link
23				// that opens the image in a new tab. Instead, the row click handler should fire.
24	
25				// Find the image cell section — look for the thumbnail img tag
26				// Current problematic pattern: <a target="_blank" href=...><img ... alt="thumb" /></a>
27				// We need to verify this pattern does NOT exist near receipt thumbnails.
28	
29				// Check that there is no <a target="_blank"> immediately before an img with alt="thumb"
30				const hasNewTabImageLink = /target="_blank"[^>]*>\s*<img[^>]*alt="thumb"/.test(pageContent);
31				expect(hasNewTabImageLink).toBe(false);
32			});
33	
34			it('opens the modal when the image is clicked (image column is not interactive)', () => {
35				// The table cell is now rendered by <DataTable>. Clicking the image must open the
36				// row's editor, which DataTable does for any non-`interactive` column. So the image
37				// column must NOT be marked interactive, and the page must wire onRowClick.
38				// (The old "no stopPropagation on the image <td>" concern is subsumed by this.)
39				const imageColumnIsPlain =
40					/key: 'image'[^}]*cell: imageCell/.test(pageContent) &&
41					!/key: 'image'[^}]*interactive/.test(pageContent);
42				const opensOnRowClick = pageContent.includes('onRowClick={openEditModal}');
43	
44				expect(imageColumnIsPlain).toBe(true);
45				expect(opensOnRowClick).toBe(true);
46			});
47	
48			it('should render image thumbnail as a plain img (not wrapped in an anchor)', () => {
49				// The receipt image thumbnail should be a plain <img> element, not wrapped
50				// in an <a> tag. This way the row click handler opens the edit modal.
51	
52				// Check that there is no anchor tag with href containing storage URL wrapping alt="thumb"
53				const hasAnchorWrappedThumb = /<a[^>]*href=\{[^}]*\}[^>]*>\s*<img[^>]*alt="thumb"/.test(
54					pageContent
55				);
56				expect(hasAnchorWrappedThumb).toBe(false);
57			});
58		});
59	
60		describe('#{#ric1b} PDF Thumbnail Click Opens Edit Modal', () => {
61			it('should NOT have target="_blank" links wrapping PDF thumbnails', () => {
62				// PDF receipt links should not open in a new tab either.
63				// The PDF icon/text should not be wrapped in <a target="_blank">
64	
65				// Look for the pattern: <a ... target="_blank" ...> near "PDF" text within the image cell
66				// After implementation, PDF should be a plain <span> or similar, not an <a>
67				const pdfSection = pageContent.match(/endsWith\('\.pdf'\)[\s\S]*?{:else}/);
68	
69				if (pdfSection) {
70					const hasPdfNewTabLink = /target="_blank"/.test(pdfSection[0]);
