4	/** Typed fake signer: returns a signed URL for any path present in `urls`, else a per-item error. */
5	function fakeSigner(urls: Record<string, string>): BatchSigner {
6		return async (paths: string[]): Promise<SignedUrlResult[]> =>
7			paths.map((p) => ({
8				path: p,
9				signedUrl: urls[p] ?? null,
10				error: urls[p] ? null : 'not found'
11			}));
12	}
13	
14	describe('collectSignedUrls', () => {
15		it('maps each path to its signed URL', async () => {
16			const sign = fakeSigner({ 'a.jpg': 'https://x/a', 'b.jpg': 'https://x/b' });
17			const result = await collectSignedUrls(['a.jpg', 'b.jpg'], sign);
18			expect(result).toEqual({ 'a.jpg': 'https://x/a', 'b.jpg': 'https://x/b' });
19		});
20	
21		it('dedupes repeated paths and drops falsy ones before signing', async () => {
22			const sign = vi.fn(fakeSigner({ 'a.jpg': 'https://x/a' }));
23			const result = await collectSignedUrls(['a.jpg', 'a.jpg', '', 'a.jpg'], sign);
24			expect(result).toEqual({ 'a.jpg': 'https://x/a' });
25			// Only the single unique, non-empty path is sent to the signer.
26			expect(sign).toHaveBeenCalledTimes(1);
27			expect(sign).toHaveBeenCalledWith(['a.jpg']);
28		});
29	
30		it('chunks paths into batches of the given size', async () => {
31			const urls: Record<string, string> = {};
32			const paths: string[] = [];
33			for (let i = 0; i < 201; i++) {
34				paths.push(`p${i}.jpg`);
35				urls[`p${i}.jpg`] = `https://x/p${i}`;
36			}
37			const sign = vi.fn(fakeSigner(urls));
38			const result = await collectSignedUrls(paths, sign, 200);
39			expect(sign).toHaveBeenCalledTimes(2); // 200 + 1
40			expect(Object.keys(result)).toHaveLength(201);
41		});
42	
43		it('drops only the paths whose items carry an error or null URL', async () => {
44			const sign = fakeSigner({ 'ok.jpg': 'https://x/ok' }); // missing.jpg has no URL → error
45			const result = await collectSignedUrls(['ok.jpg', 'missing.jpg'], sign);
46			expect(result).toEqual({ 'ok.jpg': 'https://x/ok' });
47		});
48	
49		it('soft-fails a rejecting chunk without dropping other chunks, never throwing', async () => {
50			const good = fakeSigner({ 'g0.jpg': 'https://x/g0', 'g1.jpg': 'https://x/g1' });
51			// Batch size 1 → two chunks; the second chunk's signer call rejects.
52			const sign: BatchSigner = vi.fn(async (paths) => {
53				if (paths[0] === 'bad.jpg') throw new Error('storage down');
54				return good(paths);
55			});
56			const result = await collectSignedUrls(['g0.jpg', 'bad.jpg'], sign, 1);
57			expect(result).toEqual({ 'g0.jpg': 'https://x/g0' });
58		});
